```python
def matches(events):
    for a in events:
        for b in events:
            if a is b or a['type'] != 'TURN' or b['type'] != 'DECELERATE':
                continue
            overlap = max(0.0, min(a['end'], b['end']) - max(a['start'], b['start']))
            if a['start'] < b['start'] and overlap <= 0.5 and -0.5 <= b['start'] - a['end'] <= 5.0:
                return True
    return False
```

