    events.sort(key=lambda x: x['start'])

    prev_end_time = None

    for event in events:
        if 'STOP' == event['type']:
            # Check if there was any acceleration or deceleration before this stop
            if prev_end_time is not None and prev_end_time != event['start'] + 1:
                return True

            break

        elif 'DECELERATE' == event['type']:
            # Check if there was any acceleration after this deceleration
            next_event = events[events.index(event) + 1]
            if next_event['type'] == 'ACCELERATE':
                return True

        elif 'ACCELERATE' == event['type']:
            # Check if there was any deceleration before this acceleration
            previous_event = events[events.index(event) - 1]
            if previous_event['type'] == 'DECELERATE':
                return True

        prev_end_time = event['end']

    return False
