def matches(events):
    # Sort events by start time
    events.sort(key=lambda x: x['start'])

    # Iterate through each event to check if it meets the criteria
    for i in range(len(events)):
        current_event = events[i]

        # Check if the previous event overlaps with this one or if they are both stopped
        prev_event = events[i-1] if i > 0 else None

        if prev_event:
            overlap = overlap(current_event, prev_event)

            if overlap == 0:
                return True

            elif overlap > 0.5 and overlap >= 0.8 * min(current_event['duration'], prev_event['duration']):
                return True

        # If the current event is stopping, we need to find an overlapping event
        if current_event['type'] == 'STOP':
            for j in range(i+1, len(events)):
                next_event = events[j]

                if next_event['type'] != 'STOP' and overlap(next_event, current_event) > 0.5:
                    return True

    return False
