def matches(events):
    # Check if any event sequence meets the criteria
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if events[i]['type'] == 'DECELERATE' and events[j]['type'] == 'TURN':
                start_overlap = max(0, min(events[i]['end'], events[j]['end']) - max(events[i]['start'], events[j]['start']))
                end_overlap = abs(events[i]['end'] - events[j]['start'])

                if start_overlap <= 0.5:
                    return True

                elif start_overlap > 0.5 and start_overlap >= 0.8 * min(events[i]['duration'], events[j]['duration']):
                    return True

                elif end_overlap <= 5.0:
                    return True

                elif end_overlap > 5.0 and end_overlap >= 2.0 * min(events[i]['duration'], events[j]['duration']):
                    return True

    return False
```

